/** Compact count: 980, 12.4k, 128k, 1.2M. */
export function formatTokensShort(n: number) {
  const v = Math.max(0, n)
  if (v < 1000) return `${Math.round(v)}`
  if (v < 1_000_000) {
    const k = v / 1000
    return `${k < 100 ? Number(k.toFixed(1)) : Math.round(k)}k`
  }
  const m = v / 1_000_000
  return `${m < 100 ? Number(m.toFixed(1)) : Math.round(m)}M`
}

/* -------------------------------------------------------------------------------------------------
 * Numbers
 * -----------------------------------------------------------------------------------------------*/

/** U+202F, a thin space that never breaks: 128 000, not 128,000 or 128.000. */
const THIN = " "

/** Full count with thin-space grouping: 61 000. */
export function formatTokens(n: number) {
  return Math.round(n)
    .toString()
    .replace(/\B(?=(\d{3})+(?!\d))/g, THIN)
}

export interface ContextBreakdown {
  system?: number
  tools?: number
  messages?: number
  files?: number
}

/* -------------------------------------------------------------------------------------------------
 * Types
 * -----------------------------------------------------------------------------------------------*/

export interface ContextSegment {
  /** Stable key: `system`, `tools`, `messages`, `files` or your own. */
  key: string
  label: string
  tokens: number
}

export interface ContextCompaction {
  /** Tokens freed by the summary. */
  freedTokens?: number
  /** A sentence about what happened. Defaults to "Older messages were summarized." */
  note?: React.ReactNode
}

export interface ContextMeterProps extends Omit<React.ComponentProps<"button">, "children"> {
  /** Context window size in tokens: 200000. */
  limit: number
  /** Tokens in use. Defaults to the sum of `breakdown`. */
  used?: number
  /** What fills the window. Order is kept; up to four shades plus free space. */
  breakdown?: ContextBreakdown | ContextSegment[]
  /** `ring` for a toolbar or corner, `bar` for a status line. */
  variant?: "ring" | "bar"
  /** Fraction at which the meter warns that compaction is near. Default 0.8. */
  warnAt?: number
  /** The context was just compacted. Shows a note in the popover and on the trigger. */
  compacted?: boolean | ContextCompaction
  /** Compact now. Shows a button in the warning. */
  onCompact?: () => void
  /** Model name for the popover heading, set in mono. */
  model?: React.ReactNode
  /** Show the percentage next to the ring. Default true. */
  showLabel?: boolean
}

const DEFAULT_LABELS: Record<keyof ContextBreakdown, string> = {
  system: "System",
  tools: "Tools",
  messages: "Messages",
  files: "Files",
}

function toSegments(breakdown: ContextMeterProps["breakdown"]): ContextSegment[] {
  if (!breakdown) return []
  if (Array.isArray(breakdown)) return breakdown
  return (Object.keys(DEFAULT_LABELS) as (keyof ContextBreakdown)[])
    .filter((key) => breakdown[key] !== undefined)
    .map((key) => ({ key, label: DEFAULT_LABELS[key], tokens: breakdown[key] ?? 0 }))
}

type ContextLevel = "ok" | "warn" | "critical"

/* -------------------------------------------------------------------------------------------------
 * Parts
 * -----------------------------------------------------------------------------------------------*/

/**
 * Root. Controlled with `open` and `onOpenChange`, or uncontrolled with `defaultOpen`.
 * Not modal by default: the page stays scrollable and clickable.
 */
function Popover(props: PopoverPrimitive.Root.Props) {
  return <PopoverPrimitive.Root {...props} />
}

/** The button that toggles the popover. Pass `render={<Button />}` to use your own element. */
function PopoverTrigger(props: PopoverPrimitive.Trigger.Props) {
  return <PopoverPrimitive.Trigger data-slot="popover-trigger" {...props} />
}

const LEVEL_STROKE: Record<ContextLevel, string> = {
  ok: "stroke-(color:--chatcn-fg-subtle)",
  warn: "stroke-(color:--chatcn-amber)",
  critical: "stroke-(color:--chatcn-red)",
}

/* -------------------------------------------------------------------------------------------------
 * Ring and bar
 * -----------------------------------------------------------------------------------------------*/

/** The pie is drawn as a stroke as wide as the circle, so its dash offset sweeps a sector. */
const PIE_R = 2.75

const PIE_C = 2 * Math.PI * PIE_R

/**
 * A 16 px pie inside a hairline ring. A filled sector reads as a gauge at a glance, never as a
 * spinner. It sweeps over 280 ms when usage changes, so a jump reads as growth. Past the warning
 * line it turns amber, and red when nearly full.
 */
function ContextRing({ fraction, level }: { fraction: number; level: ContextLevel }) {
  const f = Math.max(0, Math.min(1, fraction))
  return (
    <svg
      viewBox="0 0 16 16"
      fill="none"
      aria-hidden="true"
      data-slot="context-ring"
      className="size-4 shrink-0 -rotate-90 rtl:scale-x-[-1]"
    >
      <circle
        cx="8"
        cy="8"
        r="6.75"
        strokeWidth="1.25"
        className={cn(
          "transition-[stroke] duration-280 motion-reduce:transition-none",
          level === "ok" ? "stroke-(color:--chatcn-border-strong)" : LEVEL_STROKE[level],
        )}
      />
      <circle
        cx="8"
        cy="8"
        r={PIE_R}
        strokeWidth={PIE_R * 2}
        strokeDasharray={PIE_C}
        strokeDashoffset={PIE_C * (1 - f)}
        className={cn(
          "ease-(--chatcn-ease-out) transition-[stroke-dashoffset,stroke] duration-280 motion-reduce:transition-none",
          LEVEL_STROKE[level],
        )}
      />
    </svg>
  )
}

/** Ok is quiet gray, near compaction is amber, almost full is red. */
const LEVEL_FILL: Record<ContextLevel, string> = {
  ok: "bg-(color:--chatcn-fg-subtle)",
  warn: "bg-(color:--chatcn-amber)",
  critical: "bg-(color:--chatcn-red)",
}

function ContextBar({ fraction, level }: { fraction: number; level: ContextLevel }) {
  const f = Math.max(0, Math.min(1, fraction))
  return (
    <span
      aria-hidden="true"
      data-slot="context-bar"
      className="bg-(color:--chatcn-fill-active) block h-1 w-16 shrink-0 overflow-hidden rounded-full"
    >
      <span
        className={cn(
          "block h-full origin-left rounded-full rtl:origin-right",
          "ease-(--chatcn-ease-out) transition-[transform,background-color] duration-280 motion-reduce:transition-none",
          LEVEL_FILL[level],
        )}
        style={{ transform: `scaleX(${f})` }}
      />
    </span>
  )
}

interface PopoverContentProps extends PopoverPrimitive.Popup.Props {
  /** Side of the trigger to open on. Flips when there is no room. Default `bottom`. */
  side?: PopoverPrimitive.Positioner.Props["side"]
  /** Alignment along that side. Default `center`. */
  align?: PopoverPrimitive.Positioner.Props["align"]
  /** Gap to the trigger in px. Default 6. */
  sideOffset?: PopoverPrimitive.Positioner.Props["sideOffset"]
  alignOffset?: PopoverPrimitive.Positioner.Props["alignOffset"]
  /** Element to position against instead of the trigger. */
  anchor?: PopoverPrimitive.Positioner.Props["anchor"]
  /** Portal container. Defaults to `document.body`. */
  container?: PopoverPrimitive.Portal.Props["container"]
}

/** Surface shared by popovers and menus: 12 px radius, surface fill, medium shadow. */
const popupSurface = cn(
  "bg-(color:--chatcn-surface) text-(color:--chatcn-fg) shadow-(--chatcn-shadow-md) rounded-(--chatcn-radius-lg) outline-none",
  "max-h-(--available-height) max-w-(--available-width)",
  // Shadows vanish in forced colors; keep an edge.
  "forced-colors:outline-1 forced-colors:outline-solid",
)

/* -------------------------------------------------------------------------------------------------
 * Motion
 *
 * Enter: opacity, scale from 0.96 and 4 px of travel away from the trigger, 180 ms ease-(--chatcn-ease-out),
 * growing out of the trigger through `--transform-origin`. Exit: 140 ms to scale 0.98, no travel.
 * Opened or dismissed with the keyboard, Base UI sets `data-instant` and nothing animates.
 * Reduced motion keeps the fade and drops scale and travel.
 * -----------------------------------------------------------------------------------------------*/

const popupMotion = cn(
  "ease-(--chatcn-ease-out) origin-(--transform-origin) transition-[opacity,scale,translate] duration-180",
  "data-[starting-style]:scale-96 data-[starting-style]:opacity-0",
  "data-[side=bottom]:data-[starting-style]:-translate-y-1 data-[side=top]:data-[starting-style]:translate-y-1",
  "data-[side=left]:data-[starting-style]:translate-x-1 data-[side=right]:data-[starting-style]:-translate-x-1",
  "data-[side=inline-end]:data-[starting-style]:-translate-x-1 data-[side=inline-start]:data-[starting-style]:translate-x-1",
  "data-[ending-style]:scale-98 data-[ending-style]:opacity-0 data-[ending-style]:duration-140",
  "data-[instant]:transition-none",
  "motion-reduce:translate-none! motion-reduce:scale-none!",
)

/**
 * The floating panel. Portalled and positioned for you. Padding defaults to 4 px, the right inset
 * for lists; pass `className="p-3"` for text content.
 */
function PopoverContent({
  side = "bottom",
  align = "center",
  sideOffset = 6,
  alignOffset = 0,
  anchor,
  container,
  className,
  ...props
}: PopoverContentProps) {
  return (
    <PopoverPrimitive.Portal container={container}>
      <PopoverPrimitive.Positioner
        side={side}
        align={align}
        sideOffset={sideOffset}
        alignOffset={alignOffset}
        anchor={anchor}
        className="z-50 outline-none"
      >
        <PopoverPrimitive.Popup
          data-slot="popover-content"
          className={cn(
            popupSurface,
            popupMotion,
            "text-[0.875rem]/[1.25rem] tracking-[-0.003em] chatcn-scroll overflow-auto p-1",
            className,
          )}
          {...props}
        />
      </PopoverPrimitive.Positioner>
    </PopoverPrimitive.Portal>
  )
}

interface IconProps extends SVGAttributes<SVGSVGElement> {
  /** Width and height. Number means px. Default 24. */
  size?: number | string
  /** Stroke width in viewBox units (24 grid). Default 1.5. */
  strokeWidth?: number | string
  /** Keep the rendered stroke at `strokeWidth` px at any size. */
  absoluteStrokeWidth?: boolean
  /** Stroke color. Default currentColor. */
  color?: string
  /** Accessible name. Renders <title> and sets role="img"; without it the icon is aria-hidden. */
  title?: string
}

export type Icon = ForwardRefExoticComponent<IconProps & RefAttributes<SVGSVGElement>>

/** Shape elements an icon may contain. */
type IconElement = "path" | "circle" | "rect" | "ellipse" | "line" | "polyline" | "polygon"

/** An icon's drawing: a flat list of [element, attributes] pairs, lucide compatible. */
export type IconNode = ReadonlyArray<readonly [IconElement, Readonly<Record<string, string>>]>

const toPascal = (name: string): string =>
  name
    .split("-")
    .map((part) => part.charAt(0).toUpperCase() + part.slice(1))
    .join("")

/**
 * Builds a React icon component from an icon node.
 * `name` is the kebab-case icon name, used for the class `chatcn-icon-<name>` and displayName.
 */
export function createIcon(name: string, iconNode: IconNode): Icon {
  // biome-ignore lint/correctness/noComponentHookFactories: runs once per icon at module load
  const Component = forwardRef<SVGSVGElement, IconProps>(function ChatcnIcon(
    {
      size = 24,
      strokeWidth = 1.5,
      absoluteStrokeWidth = false,
      color = "currentColor",
      title,
      className,
      children,
      ...rest
    },
    ref,
  ) {
    const stroke = absoluteStrokeWidth
      ? (Number(strokeWidth) * 24) / Number.parseFloat(String(size))
      : strokeWidth
    const labelled = Boolean(title || rest["aria-label"] || rest["aria-labelledby"])
    return createElement(
      "svg",
      {
        ref,
        xmlns: "http://www.w3.org/2000/svg",
        width: size,
        height: size,
        viewBox: "0 0 24 24",
        fill: "none",
        stroke: color,
        strokeWidth: stroke,
        strokeLinecap: "round",
        strokeLinejoin: "round",
        "data-slot": "icon",
        className: className
          ? `chatcn-icon chatcn-icon-${name} ${className}`
          : `chatcn-icon chatcn-icon-${name}`,
        ...(labelled ? { role: "img" } : { "aria-hidden": true }),
        ...rest,
      },
      title ? createElement("title", null, title) : null,
      ...iconNode.map(([tag, attrs], i) => createElement(tag, { key: i, ...attrs })),
      children,
    )
  })
  Component.displayName = `${toPascal(name)}Icon`
  return Component
}

