type ButtonVariant = "solid" | "outline" | "ghost" | "subtle"

type ButtonSize = "xs" | "sm" | "md" | "lg" | "icon-xs" | "icon-sm" | "icon-md" | "icon-lg"

interface ButtonProps extends React.ComponentProps<"button"> {
  variant?: ButtonVariant
  size?: ButtonSize
}

const base = cn(
  "chatcn-focus inline-flex shrink-0 items-center justify-center gap-1.5 font-medium whitespace-nowrap select-none",
  "ease-(--chatcn-ease-standard) transition-[background-color,color,box-shadow,scale] duration-150",
  "active:scale-(--chatcn-press-scale) active:duration-100 disabled:pointer-events-none disabled:opacity-50",
  "[&_svg]:pointer-events-none [&_svg]:shrink-0",
)

const variants: Record<ButtonVariant, string> = {
  solid: "bg-(color:--chatcn-primary) text-(color:--chatcn-primary-fg) hover:bg-(color:--chatcn-primary-hover)",
  outline: "bg-(color:--chatcn-card) text-(color:--chatcn-fg) shadow-(--chatcn-shadow-xs) hover:bg-(color:--chatcn-fill-hover)",
  ghost: "text-(color:--chatcn-fg-muted) hover:bg-(color:--chatcn-fill-hover) hover:text-(color:--chatcn-fg)",
  subtle: "bg-(color:--chatcn-fill) text-(color:--chatcn-fg) hover:bg-(color:--chatcn-fill-hover)",
}

// Heights follow the control scale: 24, 28, 32, 36. Radii stay concentric inside 12 px surfaces.
const sizes: Record<ButtonSize, string> = {
  xs: "h-6 rounded-(--chatcn-radius-sm) px-2 text-[0.75rem]/[1rem] [&_svg]:size-3.5",
  sm: "h-7 rounded-(--chatcn-radius-sm) px-2.5 text-[0.8125rem]/[1.25rem] [&_svg]:size-3.5",
  md: "h-8 rounded-(--chatcn-radius-md) px-3 text-[0.875rem]/[1.25rem] tracking-[-0.003em] [&_svg]:size-4",
  lg: "h-9 rounded-(--chatcn-radius-md) px-3.5 text-[0.875rem]/[1.25rem] tracking-[-0.003em] [&_svg]:size-4",
  "icon-xs": "size-6 rounded-(--chatcn-radius-sm) active:scale-(--chatcn-press-scale-icon) [&_svg]:size-3.5",
  "icon-sm": "size-7 rounded-(--chatcn-radius-sm) active:scale-(--chatcn-press-scale-icon) [&_svg]:size-3.5",
  "icon-md": "size-8 rounded-(--chatcn-radius-md) active:scale-(--chatcn-press-scale-icon) [&_svg]:size-4",
  "icon-lg": "size-9 rounded-(--chatcn-radius-md) active:scale-(--chatcn-press-scale-icon) [&_svg]:size-4",
}

/** Class names for anything that should look like a button, such as a link. */
function buttonVariants({
  variant = "ghost",
  size = "md",
}: {
  variant?: ButtonVariant
  size?: ButtonSize
} = {}) {
  return cn(base, variants[variant], sizes[size])
}

function Button({
  variant = "ghost",
  size = "md",
  type = "button",
  className,
  ...props
}: ButtonProps) {
  return (
    <button
      type={type}
      data-slot="button"
      data-variant={variant}
      className={cn(buttonVariants({ variant, size }), className)}
      {...props}
    />
  )
}

/* -------------------------------------------------------------------------------------------------
 * ContextMeter
 * -----------------------------------------------------------------------------------------------*/

/**
 * How full the context window is, as a ring or a bar, with a breakdown on click: system prompt,
 * tool definitions, messages, files and what is left. Warns before automatic compaction and
 * says so when it happened. Token counts use tabular figures and thin-space grouping.
 */
export function ContextMeter({
  limit,
  used: usedProp,
  breakdown,
  variant = "ring",
  warnAt = 0.8,
  compacted,
  onCompact,
  model,
  showLabel = true,
  className,
  ...props
}: ContextMeterProps) {
  const segments = toSegments(breakdown)
  const used = usedProp ?? segments.reduce((sum, s) => sum + s.tokens, 0)
  const fraction = limit > 0 ? used / limit : 0
  const percent = Math.min(100, Math.round(fraction * 100))
  const warn = fraction >= warnAt
  const critical = fraction >= 0.95
  const level: ContextLevel = critical ? "critical" : warn ? "warn" : "ok"
  const free = Math.max(0, limit - used)
  const compaction = compacted ? (compacted === true ? {} : compacted) : undefined

  return (
    <Popover>
      <PopoverTrigger
        data-slot="context-meter"
        data-variant={variant}
        data-context-level={level}
        // The name starts with the visible text (WCAG 2.5.3), then says what it measures.
        aria-label={`${variant === "bar" ? `${formatTokensShort(used)} / ${formatTokensShort(limit)}` : `${percent}%`}${compaction ? " Compacted" : ""}, context window used: ${formatTokensShort(used)} of ${formatTokensShort(limit)} tokens`}
        className={cn(
          "chatcn-focus rounded-(--chatcn-radius-sm) text-[0.75rem]/[1rem] inline-flex h-7 shrink-0 items-center gap-1.5 px-1.5 tabular-nums select-none",
          "text-(color:--chatcn-fg-subtle) hover:bg-(color:--chatcn-fill-hover) hover:text-(color:--chatcn-fg) ease-(--chatcn-ease-standard) transition-colors duration-150",
          "data-[popup-open]:bg-(color:--chatcn-fill) data-[popup-open]:text-(color:--chatcn-fg)",
          warn && "text-(color:--chatcn-fg)",
          "pointer-coarse:h-11",
          className,
        )}
        {...props}
      >
        {variant === "ring" ? (
          <ContextRing fraction={fraction} level={level} />
        ) : (
          <ContextBar fraction={fraction} level={level} />
        )}
        {showLabel ? (
          <span className={cn(critical && "text-(color:--chatcn-red) font-medium")}>
            {variant === "bar"
              ? `${formatTokensShort(used)} / ${formatTokensShort(limit)}`
              : `${percent}%`}
          </span>
        ) : null}
        {compaction ? <span className="text-(color:--chatcn-fg-subtle)">Compacted</span> : null}
      </PopoverTrigger>

      <PopoverContent aria-label="Context window" side="bottom" align="end" className="w-72 p-0">
        <div className="flex flex-col gap-3 p-3.5">
          <div className="flex items-start gap-2.5">
            <ContextWindowIcon
              aria-hidden="true"
              className="text-(color:--chatcn-fg-subtle) mt-0.5 size-4 shrink-0"
            />
            <div className="flex min-w-0 flex-1 flex-col">
              <span className="text-[0.875rem]/[1.25rem] tracking-[-0.003em] text-(color:--chatcn-fg) font-medium">Context window</span>
              <span className="text-[0.75rem]/[1rem] text-(color:--chatcn-fg-subtle) tabular-nums">
                {formatTokens(used)} of {formatTokens(limit)} tokens
              </span>
              {model ? (
                <span className="text-[0.75rem]/[1rem] text-(color:--chatcn-fg-subtle) truncate font-mono">
                  {model}
                </span>
              ) : null}
            </div>
            <span className="text-[0.875rem]/[1.25rem] tracking-[-0.003em] text-(color:--chatcn-fg) font-medium tabular-nums">
              {percent}%
            </span>
          </div>

          {segments.length > 0 ? (
            <>
              <ContextStack segments={segments} limit={limit} />
              <dl className="text-[0.8125rem]/[1.25rem] flex flex-col gap-1">
                {segments.map((segment, i) => (
                  <div key={segment.key} className="flex h-5 items-center gap-2">
                    <span
                      aria-hidden="true"
                      className={cn("size-2 shrink-0 rounded-[2px]", SHADES[i % SHADES.length])}
                    />
                    <dt className="text-(color:--chatcn-fg-muted) flex-1">{segment.label}</dt>
                    <dd className="text-(color:--chatcn-fg) tabular-nums">{formatTokens(segment.tokens)}</dd>
                  </div>
                ))}
                <div className="flex h-5 items-center gap-2">
                  <span
                    aria-hidden="true"
                    className="bg-(color:--chatcn-fill-active) size-2 shrink-0 rounded-[2px] shadow-[inset_0_0_0_1px_var(--chatcn-border-strong)]"
                  />
                  <dt className="text-(color:--chatcn-fg-subtle) flex-1">Free</dt>
                  <dd className="text-(color:--chatcn-fg-subtle) tabular-nums">{formatTokens(free)}</dd>
                </div>
              </dl>
            </>
          ) : null}
        </div>

        {compaction ? (
          <div className="border-(color:--chatcn-border)/70 text-[0.8125rem]/[1.25rem] text-(color:--chatcn-fg-muted) flex gap-2.5 border-t px-3.5 py-3">
            <ContextWindowIcon
              aria-hidden="true"
              className="text-(color:--chatcn-fg-subtle) mt-0.5 size-4 shrink-0"
            />
            <p className="text-pretty">
              <span className="text-(color:--chatcn-fg) font-medium">Context compacted. </span>
              {compaction.note ?? "Older messages were summarized."}
              {compaction.freedTokens ? (
                <span className="tabular-nums">
                  {" "}
                  {formatTokensShort(compaction.freedTokens)} tokens freed.
                </span>
              ) : null}
            </p>
          </div>
        ) : warn ? (
          <div className="border-(color:--chatcn-border)/70 text-[0.8125rem]/[1.25rem] text-(color:--chatcn-fg-muted) flex flex-col gap-2.5 border-t px-3.5 py-3">
            <p className="flex gap-2.5 text-pretty">
              <CircleAlertIcon
                aria-hidden="true"
                className="text-(color:--chatcn-fg) mt-0.5 size-4 shrink-0"
              />
              <span>
                <span className="text-(color:--chatcn-fg) font-medium">{percent}% full. </span>
                Older messages will be summarized soon to make room. Compact now to choose the
                moment.
              </span>
            </p>
            {onCompact ? (
              <Button size="sm" variant="outline" onClick={onCompact} className="self-end">
                Compact now
              </Button>
            ) : null}
          </div>
        ) : null}
      </PopoverContent>
    </Popover>
  )
}

/**
 * The divider a transcript shows where compaction happened, so the user knows why the agent may
 * have forgotten details from before it.
 */
export function ContextCompactionDivider({
  freedTokens,
  className,
  children,
  ...props
}: React.ComponentProps<"div"> & { freedTokens?: number }) {
  return (
    <div
      role="note"
      data-slot="context-compaction"
      className={cn(
        "text-[0.75rem]/[1rem] text-(color:--chatcn-fg-subtle) flex min-h-8 items-center gap-3 tabular-nums",
        className,
      )}
      {...props}
    >
      <span aria-hidden="true" className="bg-(color:--chatcn-border) h-px flex-1" />
      <span className="flex items-center gap-1.5">
        <ContextWindowIcon aria-hidden="true" className="size-3.5" />
        {children ?? (
          <>
            Context compacted
            {freedTokens ? <> · {formatTokensShort(freedTokens)} tokens summarized</> : null}
          </>
        )}
      </span>
      <span aria-hidden="true" className="bg-(color:--chatcn-border) h-px flex-1" />
    </div>
  )
}

